-- ------------------------------------------------ instance zone version (full zone copy)
-- idempotent: existing version row + its spawn clones are cleared first
DELETE FROM `spawn2` WHERE `zone` = 'convorteum' AND `version` = 1;
DELETE FROM `zone` WHERE `zoneidnumber` = 491 AND `version` = 1;
DROP TEMPORARY TABLE IF EXISTS uf_zv;
CREATE TEMPORARY TABLE uf_zv AS SELECT * FROM `zone` WHERE `zoneidnumber` = 491 AND `version` = 0;
ALTER TABLE uf_zv MODIFY `id` INT NULL;
UPDATE uf_zv SET `version` = 1, `id` = NULL;
DROP TEMPORARY TABLE uf_zv;
SELECT `spawngroupID`,'convorteum',1,`x`,`y`,`z`,`heading`,86400,`variance`,`pathgrid`,`path_when_zone_idle`,`_condition`,`cond_value`,`animation`,`min_expansion`,`max_expansion`,`content_flags`,`content_flags_disabled` FROM `spawn2` WHERE `zone` = 'convorteum' AND `version` = 0;

